class MyHashMap {
  constructor(size = 1000) {
    this.buckets = Array.from({ length: size }, () => []);   // each bucket is a chain
  }
  bucket(key) {
    return this.buckets[key % this.buckets.length];          // the hash: key -> bucket
  }
  put(key, value) {
    const chain = this.bucket(key);
    for (const entry of chain) {
      if (entry[0] === key) { entry[1] = value; return; }    // existing key: overwrite
    }
    chain.push([key, value]);                                // new key: add it to the chain
  }
  get(key) {
    for (const [k, v] of this.bucket(key)) {
      if (k === key) return v;
    }
    return -1;                                               // not in its bucket: not anywhere
  }
  remove(key) {
    const chain = this.bucket(key);
    const i = chain.findIndex(([k]) => k === key);
    if (i !== -1) chain.splice(i, 1);
  }
}

class MyHashMap:
    def __init__(self, size=1000):
        self.buckets = [[] for _ in range(size)]         # each bucket is a chain

    def _bucket(self, key):
        return self.buckets[key % len(self.buckets)]     # the hash: key -> bucket

    def put(self, key, value):
        chain = self._bucket(key)
        for entry in chain:
            if entry[0] == key:
                entry[1] = value                         # existing key: overwrite
                return
        chain.append([key, value])                       # new key: add it to the chain

    def get(self, key):
        for k, v in self._bucket(key):
            if k == key:
                return v
        return -1                                        # not in its bucket: not anywhere

    def remove(self, key):
        chain = self._bucket(key)
        for i, (k, _) in enumerate(chain):
            if k == key:
                chain.pop(i)
                return

class MyHashMap {
    private final List<List<int[]>> buckets = new ArrayList<>();   // each bucket is a chain of {key, value}

    MyHashMap() {
        for (int i = 0; i < 1000; i++) buckets.add(new ArrayList<>());
    }

    private List<int[]> bucket(int key) {
        return buckets.get(key % buckets.size());     // the hash: key -> bucket
    }

    void put(int key, int value) {
        for (int[] entry : bucket(key)) {
            if (entry[0] == key) { entry[1] = value; return; }   // existing key: overwrite
        }
        bucket(key).add(new int[]{key, value});       // new key: add it to the chain
    }

    int get(int key) {
        for (int[] entry : bucket(key)) {
            if (entry[0] == key) return entry[1];
        }
        return -1;                                    // not in its bucket: not anywhere
    }

    void remove(int key) {
        bucket(key).removeIf(entry -> entry[0] == key);
    }
}

class MyHashMap {
    vector<list<pair<int, int>>> buckets;             // each bucket is a chain of {key, value}

    list<pair<int, int>>& bucket(int key) {
        return buckets[key % buckets.size()];         // the hash: key -> bucket
    }

public:
    MyHashMap() : buckets(1000) {}

    void put(int key, int value) {
        for (auto& entry : bucket(key)) {
            if (entry.first == key) { entry.second = value; return; }   // existing key: overwrite
        }
        bucket(key).push_back({key, value});          // new key: add it to the chain
    }

    int get(int key) {
        for (auto& entry : bucket(key)) {
            if (entry.first == key) return entry.second;
        }
        return -1;                                    // not in its bucket: not anywhere
    }

    void remove(int key) {
        bucket(key).remove_if([key](const pair<int, int>& e) { return e.first == key; });
    }
};
